import{_ as n,o as r,c as t,a2 as i}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"Einträge per Formular bearbeiten","description":"Bestehende Einträge über ein Formular ändern lassen — ohne Zugriff auf den Space.","frontmatter":{"title":"Einträge per Formular bearbeiten","description":"Bestehende Einträge über ein Formular ändern lassen — ohne Zugriff auf den Space."},"headers":[],"relativePath":"formulare/eintraege-bearbeiten.md","filePath":"formulare/eintraege-bearbeiten.md","lastUpdated":1786088012000}'),a={name:"formulare/eintraege-bearbeiten.md"};function s(l,e,o,d,u,g){return r(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="eintrage-per-formular-bearbeiten" tabindex="-1">Einträge per Formular bearbeiten <a class="header-anchor" href="#eintrage-per-formular-bearbeiten" aria-label="Permalink to &quot;Einträge per Formular bearbeiten&quot;">​</a></h1><p>Formulare legen nicht nur neue Einträge an. Sie können auch einen <strong>bestehenden</strong> Eintrag zur Bearbeitung öffnen — für Personen, die keinen Zugriff auf den Space haben.</p><h2 id="wofur-das-gut-ist" tabindex="-1">Wofür das gut ist <a class="header-anchor" href="#wofur-das-gut-ist" aria-label="Permalink to &quot;Wofür das gut ist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anwendung</th><th>Ablauf</th></tr></thead><tbody><tr><td><strong>Korrektur anfordern</strong></td><td>Sie schicken einen Link, die Person berichtigt ihre Angaben</td></tr><tr><td><strong>Zu- oder Absage einholen</strong></td><td>Der Eintrag existiert, nur der Status fehlt</td></tr><tr><td><strong>Unterlagen nachreichen</strong></td><td>Ein Dateifeld wird ergänzt</td></tr><tr><td><strong>Daten bestätigen lassen</strong></td><td>Jährliche Prüfung von Stammdaten</td></tr><tr><td><strong>Rückmeldung aus einem Flow</strong></td><td>Ein <a href="/flows/aktionen">Flow</a> verschickt den Link automatisch</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Kein Doppeleintrag</p><p>Der entscheidende Unterschied zu einem normalen Formular: Es entsteht <strong>kein zweiter Datensatz</strong>. Die Änderung landet im vorhandenen Eintrag.</p><p>Ohne diesen Weg schicken Menschen ihre Korrektur oft über dasselbe Anmeldeformular noch einmal — und Sie haben den Vorgang doppelt.</p></div><h2 id="einen-eintrag-zur-bearbeitung-teilen" tabindex="-1">Einen Eintrag zur Bearbeitung teilen <a class="header-anchor" href="#einen-eintrag-zur-bearbeitung-teilen" aria-label="Permalink to &quot;Einen Eintrag zur Bearbeitung teilen&quot;">​</a></h2><ol><li>Öffnen Sie das Zeilenmenü des Eintrags.</li><li>Wählen Sie <strong>Eintrag teilen</strong>.</li><li>Wählen Sie unter <em>Wählen Sie ein Formular aus</em> das zu verwendende Formular.</li></ol><p>Der Dialog heißt:</p><blockquote><p><strong>Formular zum bearbeiten teilen</strong><em>Teile ein Formular zum bearbeiten des Eintrags mit Anderen.</em></p></blockquote><p>Nach dem Erstellen:</p><blockquote><p><em>Dein Eintrag haben wir sicher veröffentlicht und ist unter der folgenden Webadresse abrufbereit.</em></p></blockquote><div class="warning custom-block"><p class="custom-block-title">Ein Formular ist Voraussetzung</p><p>Ohne Formular auf diesem Grid erscheint: <em>Erstellen Sie erst ein Formular um den Eintrag mit anderen zu teilen.</em></p><p>Legen Sie zuerst ein <a href="/formulare/formular-erstellen">Formular</a> an — am besten eines, das genau die Felder enthält, die geändert werden dürfen.</p></div><h2 id="aus-einem-flow-heraus" tabindex="-1">Aus einem Flow heraus <a class="header-anchor" href="#aus-einem-flow-heraus" aria-label="Permalink to &quot;Aus einem Flow heraus&quot;">​</a></h2><p>Der Flow-Schritt <strong>Vorausgefüllter Formularlink</strong> erzeugt denselben Link automatisch.</p><p>Damit bauen Sie Rückmeldeschleifen ohne Handarbeit:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Auslöser: Eintrag wurde geändert  (Status = „Prüfung nötig&quot;)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Vorausgefüllter Formularlink      → erzeugt den Bearbeitungslink</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>E-Mail                            → verschickt ihn an die Person</span></span></code></pre></div><p>Sendet die Person das Formular ab, greift der Auslöser <strong>Eintrag per Formular geändert</strong> — damit kann ein weiterer Flow die Rückmeldung verarbeiten.</p><p>→ <a href="/flows/trigger">Trigger</a> · <a href="/flows/aktionen">Aktionen</a></p><h2 id="formular-fur-die-bearbeitung-vorbereiten" tabindex="-1">Formular für die Bearbeitung vorbereiten <a class="header-anchor" href="#formular-fur-die-bearbeitung-vorbereiten" aria-label="Permalink to &quot;Formular für die Bearbeitung vorbereiten&quot;">​</a></h2><p>Ein Bearbeitungsformular sollte anders aufgebaut sein als ein Erfassungsformular:</p><div class="tip custom-block"><p class="custom-block-title">Nur zeigen, was geändert werden darf</p><table tabindex="0"><thead><tr><th>Ziel</th><th>Einstellung</th></tr></thead><tbody><tr><td>Feld nur anzeigen, nicht ändern</td><td><strong>Nicht änderbar</strong></td></tr><tr><td>Feld gar nicht zeigen</td><td><strong>Nicht sichtbar</strong> oder aus dem Formular entfernen</td></tr><tr><td>Vorhandene Dateien schützen</td><td><strong>Nur Hinzufügen von Dateien erlauben</strong></td></tr><tr><td>Reine Anzeige ohne Änderung</td><td><strong>Absenden-Button ausblenden</strong></td></tr></tbody></table><p>Die Einstellung <em>Absenden-Button ausblenden</em> ist ausdrücklich dafür gedacht — die Oberfläche beschreibt sie mit: <em>Dies ist nützlich, wenn Sie das Formular nutzen um eine Ansicht zu einem Eintrag mit Anderen zu teilen.</em></p></div><h2 id="sicherheit" tabindex="-1">Sicherheit <a class="header-anchor" href="#sicherheit" aria-label="Permalink to &quot;Sicherheit&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Der Link öffnet genau diesen Eintrag</p><p>Wer den Link hat, kann den Eintrag ansehen und — je nach Formular — ändern. Es gibt keine zusätzliche Prüfung, wer die Person ist.</p><p>Behandeln Sie den Link entsprechend:</p><ul><li>Verschicken Sie ihn nur an die betroffene Person.</li><li>Beschränken Sie den Zugriff über <strong>Beschränkungen festlegen</strong>, wenn der Eintrag sensibel ist.</li><li>Entfernen Sie den Link, sobald er nicht mehr gebraucht wird.</li></ul></div><p>Für Formularlinks gilt das Modell <strong>Jeder</strong> / <strong>Jeder registrierte Benutzer</strong> / <strong>Jeder aus diesem Space</strong>. → <a href="/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></p><div class="tip custom-block"><p class="custom-block-title">Kontobestätigung bei sensiblen Vorgängen</p><p>Über <em>Hinweis zur Konto-Bestätigung anzeigen</em> sehen Ausfüllende, mit welchem Konto sie angemeldet sind. An geteilten Geräten verhindert das, dass jemand unter fremdem Namen bestätigt.</p></div><h2 id="link-entfernen" tabindex="-1">Link entfernen <a class="header-anchor" href="#link-entfernen" aria-label="Permalink to &quot;Link entfernen&quot;">​</a></h2><p>Über den Freigabedialog oder in der <a href="/zusammenarbeit/externe-links">Links-Übersicht</a> des Space. Ein entfernter Link funktioniert sofort nicht mehr.</p><div class="tip custom-block"><p class="custom-block-title">Nach Abschluss aufräumen</p><p>Bearbeitungslinks entstehen im laufenden Betrieb oft in größerer Zahl — besonders, wenn ein Flow sie erzeugt. Sehen Sie die Links-Übersicht regelmäßig durch und entfernen Sie, was erledigt ist.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/formulare/formular-teilen">Formular teilen</a></li><li><a href="/formulare/vorausgefuellte-links">Vorausgefüllte Links</a></li><li><a href="/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></li></ul>`,30)])])}const b=n(a,[["render",s]]);export{c as __pageData,b as default};
